    let batch = region.get_blocks(&coords)?;
    let mut file_buffer = std::io::BufWriter::new(std::fs::File::create(output_file)?);
    for coord in &coords {
        let block = batch
            .get(*coord)?
            .ok_or(SulfurError::MissingBlockAt(*coord))?;
        file_buffer.write_all(&[block_to_byte(&block.name.to_str())?])?;
    }
    file_buffer.flush()?;
    Ok(())
